// DigiPanel Account Log Viewer.
// Streams the real access and error logs generated by the account vhost. The
// backend only exposes the closed set access.log and error.log inside the
// account home, so this view never requests arbitrary paths.

import React, { useEffect, useMemo, useState } from 'react';
import { RefreshCw, FileText, AlertCircle } from 'lucide-react';
import type { ApiAccount, Language } from '../types';
import { getTranslation } from '../i18n/translations';
import { apiFetch } from '../api/client';
import { OpsEmpty, OpsError, OpsHeader, formatDate } from './opsShared';

interface LogResponse {
  username: string;
  log: string;
  exists: boolean;
  lines: string[];
}

export const AccountLogsView: React.FC<{ language: Language }> = ({ language }) => {
  const t = (key: any) => getTranslation(language, key);
  const [accounts, setAccounts] = useState<ApiAccount[]>([]);
  const [username, setUsername] = useState('');
  const [logType, setLogType] = useState<'access' | 'error'>('access');
  const [lines, setLines] = useState<string[]>([]);
  const [exists, setExists] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [fetchedAt, setFetchedAt] = useState('');

  useEffect(() => {
    apiFetch<ApiAccount[]>('/api/v1/hosting/accounts')
      .then((data) => {
        const list = Array.isArray(data) ? data : [];
        setAccounts(list);
        if (list.length > 0) setUsername(list[0].username);
      })
      .catch((cause) => setError(cause instanceof Error ? cause.message : String(cause)));
  }, []);

  const load = async () => {
    if (!username) return;
    try {
      setLoading(true);
      setError('');
      const data = await apiFetch<LogResponse>(
        `/api/v1/hosting/accounts/logs?username=${encodeURIComponent(username)}&type=${logType}&lines=400`
      );
      setLines(Array.isArray(data.lines) ? data.lines : []);
      setExists(Boolean(data.exists));
      setFetchedAt(new Date().toISOString());
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : String(cause));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
  }, [username, logType]);

  const selectedAccount = useMemo(() => accounts.find((item) => item.username === username), [accounts, username]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
      <OpsHeader
        title={t('accessLogsTitle')}
        subtitle={t('accessLogsSubtitle')}
        action={
          <button type="button" className="btn btn-secondary btn-sm" onClick={() => void load()} disabled={loading || !username}>
            <RefreshCw size={14} />
            {t('refresh')}
          </button>
        }
      />

      {error ? <OpsError message={error} onDismiss={() => setError('')} /> : null}

      <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap', alignItems: 'center' }}>
        <select
          className="input-glass"
          style={{ width: '240px', height: '38px' }}
          value={username}
          onChange={(event) => setUsername(event.target.value)}
        >
          {accounts.length === 0 ? <option value="">{t('accessLogsNoAccounts')}</option> : null}
          {accounts.map((account) => (
            <option key={account.id} value={account.username}>
              {account.username} ({account.primaryDomain})
            </option>
          ))}
        </select>

        <div style={{ display: 'flex', gap: '4px' }}>
          <button
            type="button"
            className={logType === 'access' ? 'btn btn-primary btn-sm' : 'btn btn-secondary btn-sm'}
            onClick={() => setLogType('access')}
          >
            <FileText size={13} />
            {t('accessLogsAccess')}
          </button>
          <button
            type="button"
            className={logType === 'error' ? 'btn btn-primary btn-sm' : 'btn btn-secondary btn-sm'}
            onClick={() => setLogType('error')}
          >
            <AlertCircle size={13} />
            {t('accessLogsError')}
          </button>
        </div>

        {selectedAccount ? (
          <span className="font-mono" style={{ fontSize: '0.74rem', color: 'var(--text-muted)' }}>
            {selectedAccount.homeDir}/logs/{logType}.log
          </span>
        ) : null}
      </div>

      {loading ? (
        <div className="glass-panel" style={{ padding: '40px', textAlign: 'center', color: 'var(--text-muted)' }}>{t('appsLoading')}</div>
      ) : !exists ? (
        <OpsEmpty message={t('accessLogsEmpty')} />
      ) : (
        <div className="glass-panel" style={{ padding: '16px' }}>
          <div className="font-mono" style={{ fontSize: '0.75rem', lineHeight: 1.7, maxHeight: '520px', overflow: 'auto', whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
            {lines.length === 0 ? (
              <span style={{ color: 'var(--text-muted)' }}>{t('accessLogsEmpty')}</span>
            ) : (
              lines.map((line, index) => (
                <div key={`${index}-${line.slice(0, 24)}`} style={{ color: line.includes(' error ') || line.includes(' [error] ') ? '#ef4444' : 'var(--text-main)' }}>
                  {line}
                </div>
              ))
            )}
          </div>
          <div style={{ marginTop: '10px', fontSize: '0.7rem', color: 'var(--text-dim)' }}>
            {lines.length} {t('accessLogsLines')} {fetchedAt ? `\u00b7 ${formatDate(fetchedAt)}` : ''}
          </div>
        </div>
      )}
    </div>
  );
};
